To write unit tests for the given code, we need to test the `AddOllamaTextEmbeddingGeneration` method in the `OllamaServiceCollectionExtensions` class. This method adds the Ollama Text Embedding Generation service to the service collection.

Here's an example of how you can write unit tests for this method using xUnit:

```csharp
using Xunit;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel;
using OllamaSharp;

public class OllamaServiceCollectionExtensionsTests
{
    [Fact]
    public void AddOllamaTextEmbeddingGeneration_ServiceProvider_GetService_OllamaApiClient_ReturnsOllamaApiClient()
    {
        // Arrange
        var services = new ServiceCollection();
        services.AddTransient<OllamaApiClient>();
        var serviceProvider = services.BuildServiceProvider();

        // Act
        var ollamaClient = serviceProvider.GetService<OllamaApiClient>();

        // Assert
        Assert.NotNull(ollamaClient);
    }

    [Fact]
    public void AddOllamaTextEmbeddingGeneration_ServiceProvider_GetService_IOllamaApiClient_ReturnsOllamaApiClient()
    {
        // Arrange
        var services = new ServiceCollection();
        services.AddTransient<IOllamaApiClient>();
        var serviceProvider = services.BuildServiceProvider();

        // Act
        var ollamaClient = serviceProvider.GetService<IOllamaApiClient>() as OllamaApiClient;

        // Assert
        Assert.NotNull(ollamaClient);
    }

    [Fact]
    public void AddOllamaTextEmbeddingGeneration_ServiceProvider_GetRequiredService_IOllamaApiClient_ReturnsOllamaApiClient()
    {
        // Arrange
        var services = new ServiceCollection();
        services.AddTransient<IOllamaApiClient>();
        var serviceProvider = services.BuildServiceProvider();

        // Act
        var ollamaClient = serviceProvider.GetRequiredService<IOllamaApiClient>() as OllamaApiClient;

        // Assert
        Assert.NotNull(ollamaClient);
    }

    [Fact]
    public void AddOllamaTextEmbeddingGeneration_ServiceProvider_GetService_OllamaApiClient_ThrowsInvalidOperationException_WhenNoOllamaApiClientFound()
    {
        // Arrange
        var services = new ServiceCollection();
        var serviceProvider = services.BuildServiceProvider();

        // Act and Assert
        Assert.Throws<InvalidOperationException>(() => serviceProvider.GetService<OllamaApiClient>());
    }
}
```

These tests cover the following scenarios:

1. `AddOllamaTextEmbeddingGeneration_ServiceProvider_GetService_OllamaApiClient_ReturnsOllamaApiClient`: Tests that the `GetService` method returns an instance of `OllamaApiClient` when the service is registered in the service collection.
2. `AddOllamaTextEmbeddingGeneration_ServiceProvider_GetService_IOllamaApiClient_ReturnsOllamaApiClient`: Tests that the `GetService` method returns an instance of `OllamaApiClient` when the service is registered in the service collection as `IOllamaApiClient`.
3. `AddOllamaTextEmbeddingGeneration_ServiceProvider_GetRequiredService_IOllamaApiClient_ReturnsOllamaApiClient`: Tests that the `GetRequiredService` method returns an instance of `OllamaApiClient` when the service is registered in the service collection as `IOllamaApiClient`.
4. `AddOllamaTextEmbeddingGeneration_ServiceProvider_GetService_OllamaApiClient_ThrowsInvalidOperationException_WhenNoOllamaApiClientFound`: Tests that the `GetService` method throws an `InvalidOperationException` when the service is not registered in the service collection.

Note that these tests are just examples and you may need to modify them to fit your specific use case. Additionally, you may need to add more tests to cover other scenarios.
